def run(program):
    acc = 0
    pc = 0
    while 0 <= pc < len(program):
        parts = program[pc].split()
        op = parts[0]
        pc += 1
        if op == "HALT":
            break
        n = int(parts[1])
        if op == "ADD":
            acc += n
        elif op == "SUB":
            acc -= n
        elif op == "JMP":
            pc = n
        elif op == "JNZ":
            if acc != 0:
                pc = n
    return acc

