function run(program) {
  let acc = 0;
  let pc = 0;
  while (pc >= 0 && pc < program.length) {
    const [op, arg] = program[pc].split(" ");
    pc += 1;
    if (op === "HALT") break;
    const n = Number(arg);
    if (op === "ADD") acc += n;
    else if (op === "SUB") acc -= n;
    else if (op === "JMP") pc = n;
    else if (op === "JNZ" && acc !== 0) pc = n;
  }
  return acc;
}

